const { useState, useEffect } = React;
const root = ReactDOM.createRoot(document.querySelector('#root'));

const courses = ['자바스크립트 입문', '리액트 시작하기', 'CSS 레이아웃'];

const useSearch = (list) => {
  const [keyword, setKeyword] = useState('');

  const found = list.filter((one) => one.includes(keyword));

  useEffect(() => {
    const label = keyword === '' ? '코스 전체' : `코스 검색: ${keyword}`;
    document.title = label;
    document.querySelector('#outside').textContent = label;
  }, [keyword]);

  return { keyword: keyword, setKeyword: setKeyword, found: found };
};

const Search = () => {
  const search = useSearch(courses);

  return (
    <div className="panel">
      <label className="field" htmlFor="q">코스 검색</label>
      <input className="field__input" id="q" type="search" value={search.keyword}
        onChange={(event) => search.setKeyword(event.target.value)} />
      <p className="count">코스 {search.found.length}개</p>
      {search.found.map((course) => (
        <p className="course" key={course}>{course}</p>
      ))}
    </div>
  );
};

root.render(<Search />);
